/* ----------------------------------------------------------------------
 * Section K: S6.15-S6.19 payload vectors -- KEYBOARD (0x21), MOUSE
 * (0x22), MEDIA (0x23), INPUTCAPS (0x44).
 *
 * S15 item 10: these four types were specified on 2026-08-25 and their
 * vectors are derived independently BEFORE the codec is trusted -- the
 * opposite order to S6.12's TOUCHMAP, which S15 item 9 records as having
 * produced "agreement, not verification".
 *
 * Decode rules asserted here, each with its sentence:
 *  - keys[0] bits 0-3, reserved0/reserved1, event flags bits 1-7,
 *    MOUSE.buttons bits 5-15, MEDIA.held bits 24-31, INPUTCAPS features
 *    bits 3-31 / status bits 4-31 / media_mask bits 24-31: reserved, so
 *    SCRUBBED on decode (S2, S6.20 "Reserved *bits* ... are masked on
 *    both sides").
 *  - an events[] slot whose usage is 0x00-0x03 (S6.15), whose button is
 *    outside 1..5 (S6.16), or whose control is outside S6.18's assigned
 *    1..24 (S6.17) decodes as code 0 AND flags 0. The forced flags is what
 *    makes two decoded structures comparable for exact equality.
 *  - HID usages 0xA5-0xAF, 0xDE-0xDF and 0xE8-0xFF are passed through
 *    UNCHANGED (S6.15). A vector asserting they are scrubbed would be a
 *    spec violation, not a stricter test.
 *  - accumulators (S6.16) are raw: "the absolute value of an accumulator
 *    carries no meaning", so nothing normalises them and the signed
 *    distance is Section L's and Section M's job.
 *
 * Most rings below are RIGHT-ALIGNED as S6.20 requires. The exceptions are
 * deliberate and named in each vector's comment: a ring carrying an
 * out-of-range code, or a "no event" slot in the middle, could not have
 * been produced by a conforming sender -- and those are exactly the inputs
 * the receive-side normalisation exists for.
 * ---------------------------------------------------------------------- */

typedef struct {
    const char *name;
    const uint8_t *packet;
    uint32_t packet_len;
    uint8_t  exp_keys[32];          /* keys[0] bits 0-3 scrubbed */
    uint16_t exp_event_seq;
    uint8_t  exp_event_code[8];     /* 0 = no event (S6.20) */
    uint8_t  exp_event_flags[8];    /* bit 0 DOWN; 0 whenever code is 0 */
    uint32_t exp_client_ticks_ms;
    const uint8_t *exp_encoded;    /* S2: the canonical payload an
                                    * encoder MUST emit from the
                                    * expected decoded structure */
} apad_vec_keyboard;

