/* ----------------------------------------------------------------------
 * Section M: sequence vectors (S13 shape 3) -- an ordered list of packets
 * with the expected receiver state after EVERY step. S13: "A sequence
 * vector asserts after every step, not only at the end, or a design that
 * converges by accident passes."
 *
 * The receiver is S6.20's and nothing more: a per-type sliding window on
 * the HEADER sequence, then steps 1-4 on the payload's event_seq, plus
 * S6.16's three accumulator rules for MOUSE. Every field below is the
 * state AFTER the step, including after a step the window discards -- in
 * which case it MUST equal the state before it, motion included.
 *
 * exp_replay_code/flags list the events replayed by THIS step, in the
 * ascending slot order S6.20 mandates, with "no event" slots already
 * skipped. exp_keys/exp_buttons/exp_held are the reconciled held state
 * (step 3), which is always the datagram's snapshot -- the ring only adds
 * back what a snapshot cannot express.
 *
 * INPUTCAPS has no sequence here: S6.20 gives it a per-type window too,
 * but it is server->client, so that window lives in the client's session
 * state rather than in core. Named rather than invented.
 * ---------------------------------------------------------------------- */

#define APAD_VEC_KBM_CLS_KEYBOARD 0
#define APAD_VEC_KBM_CLS_MOUSE    1
#define APAD_VEC_KBM_CLS_MEDIA    2

typedef struct {
    const uint8_t *packet;
    uint32_t packet_len;
    uint8_t  exp_accepted;       /* 0 = S6.20 window discards it */
    uint8_t  exp_overflow;       /* S6.20 step 2, g > D */
    uint8_t  exp_replay_len;     /* events replayed by this step */
    uint8_t  exp_replay_code[8];
    uint8_t  exp_replay_flags[8];
    uint8_t  exp_keys[32];       /* KEYBOARD held state after the step */
    uint16_t exp_buttons;        /* MOUSE held state after the step   */
    uint32_t exp_held;           /* MEDIA held state after the step   */
    int32_t  exp_dx;             /* S6.16 motion attributed to this   */
    int32_t  exp_dy;             /* step; zero for the first accepted */
    int32_t  exp_wheel;          /* sample and for a discarded one    */
    int32_t  exp_hwheel;
    uint16_t exp_last_applied;   /* S6.20 step 4 */
} apad_vec_kbm_step;

typedef struct {
    const char *name;
    uint8_t  cls;                /* APAD_VEC_KBM_CLS_* */
    uint8_t  msg_type;
    uint8_t  ring_depth;         /* 8 for KEYBOARD, 4 otherwise (S6.20) */
    const apad_vec_kbm_step *steps;
    uint32_t step_count;
} apad_vec_kbm_sequence;

