/* ----------------------------------------------------------------------
 * Section N: encode vectors for S6.15-S6.19.
 *
 * An encoder owes exactly two things here, both from S2, both testable:
 * reserved BYTES zero on send (KEYBOARD's and MEDIA's reserved0/reserved1,
 * INPUTCAPS's reserved0 -- none of which exist in the in-memory structs, so
 * they have to be written deliberately rather than copied), and reserved
 * BITS masked on send (S6.20: "Reserved *bits* ... are masked on both
 * sides").
 *
 * Each *_reserved_ones vector hands the encoder a struct with every
 * maskable reserved bit set and requires byte-identical output to its
 * *_clean twin -- the encode-side mirror of S6.15's byte-identity property,
 * and the check that catches an encoder trusting its caller.
 *
 * What is deliberately NOT here: any out-of-range event code. S6.20 says an
 * encoder "is not required to normalise them, and SHOULD NOT", and a SHOULD
 * is not a vector. The generator asserts no such code reaches this table.
 *
 * The round-trip property -- encode(expected decoded structure) reproduces
 * the golden bytes -- is carried by exp_encoded on the Section K tables
 * instead, so that every packet vector contributes one. That is the check
 * a decode-only suite cannot make: an offset that is self-consistently
 * wrong in both directions decodes and re-encodes perfectly and is visible
 * only against bytes fixed by the spec.
 * ---------------------------------------------------------------------- */

typedef struct {
    const char *name;
    uint8_t  msg_type;          /* which of the four structs to build */
    /* Caller-supplied IN-MEMORY values, reserved bits included. Only the
     * fields belonging to msg_type's struct are meaningful. */
    uint8_t  in_keys[32];
    uint16_t in_dx;
    uint16_t in_dy;
    uint16_t in_wheel;
    uint16_t in_hwheel;
    uint16_t in_buttons;
    uint32_t in_held;
    uint32_t in_features;
    uint32_t in_status;
    uint32_t in_media_mask;
    uint16_t in_mouse_rate_hz;
    uint16_t in_event_seq;
    uint8_t  in_event_code[8];
    uint8_t  in_event_flags[8];
    uint32_t in_client_ticks_ms;
    const uint8_t *exp_payload; /* the exact bytes that MUST be emitted */
    uint32_t exp_payload_len;
} apad_vec_kbm_encode;

/* S6.15 encode: every field at its stated offset, reserved0/reserved1 written as zero by the encoder (they do not exist in the struct) */
